package org.sleepwell.app;
import org.json.*;import org.junit.Test;import static org.junit.Assert.*;
public final class PowerNapNativeTest {
 @Test public void strictOptionalMetadataKeepsLegacyEncodingAndRejectsMalformedBounds()throws Exception{try(PowerNapFixture f=new PowerNapFixture()){NapPlan normal=NapPlan.create(f.clock,20,0,false);JSONObject legacy=NapPlanJson.encode(normal);assertEquals(10,legacy.length());assertFalse(legacy.has("minimumRestMinutes"));assertEquals(legacy.toString(),NapPlanJson.encode(NapPlanJson.decode(legacy)).toString());NapPlan power=NapPlan.createPower(f.clock,20,15,0,false);JSONObject valid=NapPlanJson.encode(power);assertEquals(11,valid.length());assertEquals(20,NapPlanJson.decode(valid).minimumRestMinutes);for(Object n:new Object[]{0,-1,35,20.5,"20",JSONObject.NULL}){JSONObject bad=new JSONObject(valid.toString()).put("minimumRestMinutes",n);assertThrows(JSONException.class,()->NapPlanJson.decode(bad));}JSONObject unknown=new JSONObject(valid.toString()).put("hidden",true);assertThrows(JSONException.class,()->NapPlanJson.decode(unknown));Alarm a=new Alarm(2);a.nap=power;a.smartWindow=5;Alarm reopened=Alarm.read(a.json());assertFalse(reopened.napInvalid);assertEquals(20,reopened.nap.minimumRestMinutes);assertFalse(reopened.nap.smartReady(f.clock,60,1,3,100));}}
 @Test public void privateSaveReopenAtomicBackupRejectionAndInactiveRestorePreserveMinimum()throws Exception{try(PowerNapFixture f=new PowerNapFixture()){Alarm draft=new Alarm(0);draft.smartWindow=0;Alarm saved=Naps.start(f.c,draft,35,0,false,20);assertEquals(2100000,f.delay);assertEquals(20,f.load(saved.id).nap.minimumRestMinutes);assertThrows(IllegalStateException.class,()->Naps.start(f.c,saved,35,0,false,20));JSONObject valid;try(Store s=f.open()){valid=s.backup();Backup.validate(valid);JSONObject bad=new JSONObject(valid.toString());bad.getJSONArray("alarms").getJSONObject(1).getJSONObject("nap").put("minimumRestMinutes",0);String before=s.backup().toString();assertThrows(JSONException.class,()->Backup.restoreData(s,bad));assertEquals(before,s.backup().toString());Backup.restoreData(s,valid);}Alarm restored=f.load(saved.id);assertFalse(restored.enabled);assertEquals(NapPlan.Phase.CANCELLED,restored.nap.phase);assertEquals(20,restored.nap.minimumRestMinutes);assertEquals(saved.nap.nonce,restored.nap.nonce);Naps.receive(f.c,saved.id,saved.nap.nonce);assertEquals(0,f.fires);}}
 @Test public void realOwnedMotionAdmissionRereadsConfigProtectsMinimumAndLeavesLatestWhenUnavailable()throws Exception{try(PowerNapFixture f=new PowerNapFixture()){f.motion=true;Alarm draft=new Alarm(0);draft.smartWindow=15;Alarm saved=Naps.start(f.c,draft,35,0,false,20);assertFalse(Naps.movement(f.c,saved,1,3,100));f.clock.advance(1200000);f.motion=false;assertFalse(Naps.movement(f.c,saved,1,3,100));f.motion=true;try(Store s=f.open()){Alarm current=s.alarm(saved.id);current.smartWindow=0;s.save(current);}assertFalse(Naps.movement(f.c,saved,1,3,100));assertEquals(0,f.fires);f.clock.advance(900000);Naps.receive(f.c,saved.id,saved.nap.nonce);Naps.receive(f.c,saved.id,saved.nap.nonce);assertEquals(1,f.fires);assertEquals(NapPlan.Phase.CLAIMED,f.load(saved.id).nap.phase);}}
}
